import math


def sigmoid(z):
    if z >= 0:
        return 1 / (1 + math.exp(-z))
    e = math.exp(z)          # z is negative here, so e is small and cannot overflow
    return e / (1 + e)


def logistic_step(w, b, X, y, lr):
    n = len(X)
    errors = [sigmoid(sum(wj * xj for wj, xj in zip(w, row)) + b) - target for row, target in zip(X, y)]
    new_w = [wj - lr * sum(e * row[j] for e, row in zip(errors, X)) / n for j, wj in enumerate(w)]
    new_b = b - lr * sum(errors) / n
    return new_w, new_b
